def get_operation():
    """Get user input for the arithmetic operation."""
    while True:
        operation = input("Choose an operation (+, -, *, /): ").upper()
        if operation in ['+', '-', '*', '/']:
            return operation
        else:
            print("Invalid input. Please try again.")

def get_numbers():
    """Get user input for two numbers."""
    while True:
        try:
            number1 = float(input("Number 1: "))
            number2 = float(input("Number 2: "))
            return number1, number2
        except ValueError:
            print("Invalid input. Please enter numbers only.")

def perform_operation(operation, number1, number2):
    """Perform the chosen arithmetic operation."""
    if operation == '+':
        result = number1 + number2
    elif operation == '-':
        result = number1 - number2
    elif operation == '*':
        result = number1 * number2
    elif operation == '/':
        if number2 == 0:
            print("Error: Division by zero. Please try again.")
            return None
        result = number1 / number2
    else:
        print("Invalid operation. Please try again.")
        return None
    return result

def main():
    """Run the program."""
    operation = get_operation()
    if operation:
        number1, number2 = get_numbers()
        result = perform_operation(operation, number1, number2)
        if result is not None:
            print(f"Result: {result}")

if __name__ == "__main__":
    main()
